import { LiquidMetal, type LiquidMetalProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShaderLiquidMetalProps
  extends Omit<LiquidMetalProps, "frame" | "ref"> {}

function ShaderLiquidMetalBase({
  speed = 1,
  colorBack = "#2a2a30",
  colorTint = "#8a8a95",
  distortion = 0.1,
  repetition = 1.5,
  contour = 0.4,
  softness = 0.05,
  shape = "none",
  className,
  ...rest
}: ShaderLiquidMetalProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-liquid-metal"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <LiquidMetal
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colorTint={colorTint}
        distortion={distortion}
        repetition={repetition}
        contour={contour}
        softness={softness}
        shape={shape}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  distortion: {
    type: "number",
    min: 0,
    max: 0.5,
    step: 0.01,
    default: 0.1,
    description: "Distortion",
    hiddenFromList: false,
  },
  repetition: {
    type: "number",
    min: 1,
    max: 6,
    step: 0.5,
    default: 1.5,
    description: "Repetition",
    hiddenFromList: false,
  },
  contour: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.4,
    description: "Contour",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#2a2a30",
    description: "Background",
  },
  colorTint: {
    type: "color",
    default: "#8a8a95",
    description: "Tint",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","distortion","repetition","contour","colorBack","colorTint"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  distortion: 0.1,
  repetition: 1.5,
  contour: 0.4,
  colorBack: "#2a2a30",
  colorTint: "#8a8a95",
};

type ShaderLiquidMetalElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderLiquidMetalBase>;

const ShaderLiquidMetalInner = forwardRef<
  HTMLDivElement,
  ShaderLiquidMetalElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderLiquidMetal>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderLiquidMetalBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderLiquidMetalBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderLiquidMetal = Interactive.withSchema({
  Component: ShaderLiquidMetalInner,
  componentName: "<ShaderLiquidMetal>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
